/* Liga Nacional Primera Masculina - registro offline independiente */
function ligaNumber(x){if(x===null||x==='')return null;const n=Number(x);return Number.isInteger(n)&&n>=0&&n<=300?n:null}
function ligaFrames(p){return p.frames[ligaGame]||[]}
function ligaAutoScore(p){
 const rows=ligaFrames(p);
 const entry=(r)=>r&&r.a!==null&&r.a!==undefined;
 const monitor=(r)=>r&&r.monitor!==null&&r.monitor!==undefined&&r.monitor!==''?Number(r.monitor):null;
 const details=Array.from({length:10},()=>({score:null,kind:'',status:'sin datos',source:'pendiente'}));
 // Una referencia no equivale al tanteo de los lanzamientos. Un ancla
 // de cuadro abierto y puntuación confirmada permite reanudar sin doble conteo.
 let running=0,from=0,mode='calculado',anchor=null;
 for(let i=0;i<10;i++){
  const r=rows[i];if(monitor(r)===null)continue;
  anchor={idx:i,score:monitor(r),kind:r.kind||'',canContinue:r.kind==='O'};
 }
 if(anchor && rows.slice(0,anchor.idx).some(r=>!entry(r))){
  details[anchor.idx]={score:anchor.score,kind:anchor.kind,status:anchor.canContinue?'referencia confirmada':'referencia del monitor',source:'monitor'};
  if(anchor.canContinue){running=anchor.score;from=anchor.idx+1;mode='referencia + cálculo';}
  else {
   // Sin conocer los bonus asociados a X o /, no se puede deducir un
   // total posterior matemáticamente a partir de un solo acumulado.
   for(let i=anchor.idx+1;i<10;i++)if(entry(rows[i]))details[i]={score:null,kind:rows[i].kind||'',status:'bonus anterior desconocido',source:'pendiente'};
   return {score:anchor.score,frame:anchor.idx+1,source:'monitor (sin continuidad)',pending:true,details,anchor:true};
  }
 }
 let lastFrame=from;
 for(let i=from;i<10;i++){
  const r=rows[i];if(!entry(r))break;
  const a=Number(r.a),b=r.b===null?null:Number(r.b),c=r.c===null?null:Number(r.c);
  const kind=i<9?(a===10?'X':b===null?'':a+b===10?'/':'O'):(a===10?'X':b!==null&&a+b===10?'/':'O');
  const next=[];
  for(let j=i+1;j<10&&next.length<2;j++){
   const q=rows[j];if(!entry(q))break;
   next.push(Number(q.a));
   if(j===9){if(q.b!==null)next.push(Number(q.b));if(q.c!==null)next.push(Number(q.c));}
   else if(q.a!==10&&q.b!==null)next.push(Number(q.b));
  }
  let earned=null;
  if(i===9){
   if(a===10){if(b!==null&&c!==null)earned=10+b+c;}
   else if(b!==null&&a+b===10){if(c!==null)earned=10+c;}
   else if(b!==null)earned=a+b;
  }else if(a===10){if(next.length>=2)earned=10+next[0]+next[1];}
  else if(b===null)earned=null;
  else if(a+b===10){if(next.length)earned=10+next[0];}
  else earned=a+b;
  if(earned===null){details[i]={score:null,kind,status:'bonificación pendiente',source:'pendiente'};break;}
  running+=earned;lastFrame=i+1;
  details[i]={score:running,kind,status:'calculado',source:mode};
 }
 // Las anotaciones manuales posteriores nunca se suman encima del tanteo
 // calculado: solo pueden tomarse como una lectura alternativa del monitor.
 const latestMonitor=rows.reduce((last,r,i)=>monitor(r)!==null?{frame:i+1,score:monitor(r),kind:r.kind||''}:last,null);
 if(latestMonitor&&latestMonitor.frame>lastFrame){
  details[latestMonitor.frame-1]={score:latestMonitor.score,kind:latestMonitor.kind,status:'referencia del monitor',source:'monitor'};
  return {score:latestMonitor.score,frame:latestMonitor.frame,source:'monitor',pending:true,details,anchor:true};
 }
 if(lastFrame>0)return {score:running,frame:lastFrame,source:mode,pending:lastFrame<10,details,anchor:!!anchor};
 if(latestMonitor)return {score:latestMonitor.score,frame:latestMonitor.frame,source:'monitor',pending:true,details,anchor:true};
 return {score:null,frame:0,source:'pendiente',pending:true,details,anchor:false};
}
function ligaLast(p){return ligaAutoScore(p)}
function ligaSum(t,team){const players=ligaCurrent().players.filter(p=>p.trio===t&&p.team===team);const scored=players.map(ligaLast);return {total:scored.reduce((v,r)=>v+(r.score??0),0),count:scored.filter(r=>r.score!==null).length,frames:scored.reduce((v,r)=>v+r.frame,0),approx:scored.some(r=>r.source.startsWith('monitor')||r.frame<10)}}
function ligaDetailHTML(r){return `<span class="liga-frame-meta">${r.score===null?'—':r.score} <small>${r.status==='calculado'?'✓':r.source==='monitor'?'monitor':r.status==='bonificación pendiente'?'⏳':'·'}</small></span>`}
function ligaChange(i,f,k,value){const p=ligaCurrent().players[i];if(!p)return;const row=p.frames[ligaGame][f];if(k==='kind')row[k]=value;else if(value==='')row[k]=null;else {const n=ligaNumber(value);if(n===null)return;row[k]=n;}if(k==='a'&&row.a===10&&f<9)row.b=null;if(k==='a'||k==='b'||k==='c')row.kind=f===9?'':row.a===10?'X':row.a!==null&&row.b!==null&&row.a+row.b===10?'/':row.a!==null&&row.b!==null?'O':'';ligaSave();ligaUpdateLive();}
function ligaSetPlayer(i,name){ligaCurrent().players[i].name=name;ligaSave()}
function ligaSetHeader(k,v){ligaCurrent()[k]=v;ligaSave()}
function ligaSelect(i){ligaSelected=i;render();document.getElementById('liga-editor')?.scrollIntoView({behavior:'smooth',block:'start'})}
function ligaPickPlayer(i){ligaSelected=Number(i);render();document.getElementById('liga-editor')?.scrollIntoView({block:'start'});}
function ligaNew(){if(ligaData.matches.length>=21)return alert('Límite de 21 enfrentamientos en esta prueba.');let m=ligaBlank();m.match=ligaData.matches.length+1;let prev=ligaCurrent();m.myTeam=prev.myTeam;m.players.forEach((p,i)=>p.name=prev.players[i]?.name||p.name);ligaData.matches.push(m);ligaMatch=ligaData.matches.length-1;ligaGame=0;ligaSelected=0;ligaSave();render()}
function ligaAddSnapshot(){const f=Number(document.getElementById('liga-frame')?.value)-1;const p=ligaCurrent().players[ligaSelected];if(!p||f<0||f>9)return;const v=document.getElementById('liga-checkpoint').value;if(v==='')return alert('Introduce la puntuación del monitor.');const n=ligaNumber(v);if(n===null)return alert('Puntuación inválida.');p.frames[ligaGame][f].monitor=n;p.frames[ligaGame][f].kind=document.getElementById('liga-kind').value;p.startFrame=Math.min(p.startFrame||10,f+1);ligaSave();render();}
function ligaUpdateLive(){const m=ligaCurrent();for(let t=1;t<=2;t++){const a=ligaSum(t,'own'),b=ligaSum(t,'rival');const el=document.getElementById('liga-total-'+t);if(el)el.textContent=`${a.total} – ${b.total} · ${a.count}/3 y ${b.count}/3 jugadores`;const diff=document.getElementById('liga-diff-'+t);if(diff)diff.textContent=`${a.total-b.total>0?'+':''}${a.total-b.total} bolos registrados (provisional; avance desigual)`;}const full=document.getElementById('liga-grand');if(full){const x=ligaSum(1,'own').total+ligaSum(2,'own').total,y=ligaSum(1,'rival').total+ligaSum(2,'rival').total;full.textContent=`${x} – ${y}`}}
function ligaPopulateDemo(m){m.rival='Rival (simulación)';m.myTeam='Mi equipo (simulación)';m.demo=true;m.players.forEach((p,i)=>{p.frames[0][0].a=i%3===0?10:7+i%3;p.frames[0][0].b=p.frames[0][0].a===10?null:2;p.frames[0][1].a=i%2?8:10;p.frames[0][1].b=i%2?2:null;p.frames[0][2].a=7;p.frames[0][2].b=2;if(i===4){p.frames[0][0]={a:null,b:null,c:null,monitor:null,kind:''};p.frames[0][1]={a:null,b:null,c:null,monitor:null,kind:''};p.frames[0][2]={a:null,b:null,c:null,monitor:62,kind:'O'};p.frames[0][3].a=10;}})}
// Seeds a sample only when no league data has been saved yet.
if(!localStorage.getItem(LIGA_KEY)){ligaPopulateDemo(ligaData.matches[0]);ligaSave();}
function ligaDemo(){
 if(!confirm('Crear un NUEVO enfrentamiento de demostración con datos ficticios, sin modificar los que ya tengas guardados?'))return;
 ligaNew();ligaPopulateDemo(ligaCurrent());
 ligaSave();render();
}
function ligaExport(){const blob=new Blob([JSON.stringify({version:1,league:ligaData},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Mi_Bowling_Liga_'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function ligaView(){const m=ligaCurrent();if(!m)return '<p>Sin enfrentamientos.</p>';if(!m.players[ligaSelected])ligaSelected=0;const p=m.players[ligaSelected];const latest=ligaLast(p);return `${head('Liga Nacional','Primera División Masculina · 2026–27',`<button class="btn outline" onclick="newMode='oficial';competitionFormat='liga';go('nueva')">Volver</button>`)}
<div class="card"><div class="row wrap"><label>Enfrentamiento</label><select class="input" style="max-width:210px" onchange="ligaMatch=Number(this.value);ligaGame=0;ligaSelected=0;render()">${ligaData.matches.map((x,i)=>`<option value="${i}" ${i===ligaMatch?'selected':''}>Encuentro ${x.match||i+1} · ${esc(x.rival)}</option>`).join('')}</select></div><button class="btn outline mt12" onclick="ligaNew()">+ Nuevo enfrentamiento</button><button class="btn outline mt12" onclick="ligaDemo()">🎯 Crear simulación de prueba</button><label class="field">Mi equipo</label><input class="input" value="${esc(m.myTeam)}" onchange="ligaSetHeader('myTeam',this.value)"><label class="field">Equipo rival</label><input class="input" value="${esc(m.rival)}" onchange="ligaSetHeader('rival',this.value)"><label class="field">Fecha</label><input class="input" type="date" value="${esc(m.date)}" onchange="ligaSetHeader('date',this.value)"></div>
<div class="seg mb16"><button class="${ligaGame===0?'active':''}" onclick="ligaGame=0;render()">Partida 1</button><button class="${ligaGame===1?'active':''}" onclick="ligaGame=1;render()">Partida 2</button></div>
<div class="card"><h2>Marcador de bolos registrados</h2><div class="liga-score-big" id="liga-grand">${ligaSum(1,'own').total+ligaSum(2,'own').total} – ${ligaSum(1,'rival').total+ligaSum(2,'rival').total}</div><p class="hint">Calcula automáticamente los cuadros cerrados cuando se conocen sus lanzamientos. Para registros que empiezan a mitad, usa la referencia del monitor. Las bonificaciones pendientes no se suman anticipadamente; los totales siguen siendo provisionales.</p></div>
<div class="card" id="liga-editor"><h2>Registrar puntuación</h2><label class="field" for="liga-player-picker">Seleccionar jugador directamente</label><select class="input" id="liga-player-picker" onchange="ligaPickPlayer(this.value)">${[1,2].map(t=>`<optgroup label="Tripleta ${t} · ${esc(m.myTeam)}">${m.players.map((pl,i)=>pl.trio===t&&pl.team==='own'?`<option value="${i}" ${ligaSelected===i?'selected':''}>${esc(pl.name)}</option>`:'').join('')}</optgroup><optgroup label="Tripleta ${t} · ${esc(m.rival)}">${m.players.map((pl,i)=>pl.trio===t&&pl.team==='rival'?`<option value="${i}" ${ligaSelected===i?'selected':''}>${esc(pl.name)}</option>`:'').join('')}</optgroup>`).join('')}</select><p class="hint">Jugador seleccionado: <strong>${esc(p.name)}</strong> · Tripleta ${p.trio} · ${p.team==='own'?'Mi equipo':'Rival'}</p><label class="field">Editar nombre del jugador</label><input class="input" value="${esc(p.name)}" onchange="ligaSetPlayer(${ligaSelected},this.value);render()"><p class="hint">Anota los lanzamientos: la puntuación se calcula automáticamente al resolverse las bonificaciones de plenos y semis. Si empiezas a mitad de partida, usa la referencia inicial del monitor solo para los cuadros desconocidos.</p><div class="liga-scoring-explain"><strong>Acumulado: ${latest.score??'—'} puntos</strong> · ${esc(latest.source)}<p class="hint">${latest.source.startsWith('monitor')?'Referencia externa: no se pueden reconstruir los cuadros que faltan. No se han inventado bonificaciones.':'Se suman únicamente los cuadros cuyo bonus está resuelto. Los restantes están pendientes.'}</p></div><div class="liga-frame-grid">${ligaFrames(p).map((r,i)=>`<button class="liga-frame-pill" onclick="document.getElementById('liga-frame').value='${i+1}';ligaShowFrame()"><b>${i+1}</b><span>${r.monitor===null?(r.a===null?'—':(r.a===10?'X':r.b===null?String(r.a):`${r.a}+${r.b}`)):'M '+r.monitor}</span><small>${r.kind||''} · ${latest.details[i].score===null?'⏳':latest.details[i].score}</small></button>`).join('')}</div><label class="field">Cuadro a registrar</label><select class="input" id="liga-frame" onchange="ligaShowFrame()">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i+1===(latest.frame||4)?'selected':''}>Cuadro ${i+1}</option>`).join('')}</select><div class="liga-editor-fields"><label>Primer tiro <input id="liga-roll-a" class="input" type="number" min="0" max="10" placeholder="Bolos" /></label><label>Segundo tiro <input id="liga-roll-b" class="input" type="number" min="0" max="10" placeholder="Bolos" /></label><label id="liga-roll-third-label" style="display:none">Tiro extra 10.º <input id="liga-roll-c" class="input" type="number" min="0" max="10" placeholder="Bolos" /></label></div><button class="btn primary block mt12" onclick="ligaSaveRolls()">Guardar lanzamientos y calcular puntuación</button><details class="mt12"><summary><strong>¿Empiezas a mitad de partida? Introducir referencia del monitor</strong></summary><p class="hint">Úsalo solo si faltan cuadros anteriores. Para continuar un cálculo automático desde la referencia, esta debe ser una puntuación confirmada al final de un cuadro abierto. Si termina en pleno o semi, se conservará como referencia del monitor sin inventar bonus.</p><label class="field">Puntuación acumulada de referencia</label><input id="liga-checkpoint" class="input" type="number" min="0" max="300" placeholder="Por ejemplo, 78"><label class="field">Tipo de cuadro</label><select class="input" id="liga-kind"><option value="">No determinado</option><option value="X">X · Pleno</option><option value="/">/ · Semi</option><option value="O">Abierto</option></select><button class="btn outline block mt12" onclick="ligaAddSnapshot()">Guardar referencia del monitor</button></details></div>
${[1,2].map(t=>`<div class="card liga-trio"><h2>Tripleta ${t}</h2><div class="liga-summary" id="liga-total-${t}">${ligaSum(t,'own').total} – ${ligaSum(t,'rival').total} · ${ligaSum(t,'own').count}/3 y ${ligaSum(t,'rival').count}/3 jugadores</div><p class="hint" id="liga-diff-${t}">${ligaSum(t,'own').total-ligaSum(t,'rival').total} bolos registrados (no comparables si faltan jugadores o cuadros)</p>${['own','rival'].map(team=>`<h3>${team==='own'?esc(m.myTeam):esc(m.rival)}</h3>${m.players.map((pl,i)=>pl.trio===t&&pl.team===team?`<button class="liga-player ${ligaSelected===i?'chosen':''}" onclick="ligaSelect(${i})"><span>${esc(pl.name)}</span><span>${ligaLast(pl).score??'—'} <small>F${ligaLast(pl).frame||'—'} · ${ligaLast(pl).source}</small></span></button>`:'').join('')}`).join('')}</div>`).join('')}
<div class="card"><h2>Control durante el encuentro</h2><p class="hint">Las sumas comparan los últimos acumulados disponibles por tripleta. No se otorgarán los 10 puntos de Liga con marcadores incompletos. Para calcular individuales, tríos y bolos oficiales habrá que confirmar los 12 resultados finales de cada partida.</p><button class="btn outline block" onclick="ligaExport()">↓ Exportar copia de la Liga</button></div>`}
function ligaShowFrame(){const p=ligaCurrent().players[ligaSelected],f=Number(document.getElementById('liga-frame').value)-1,r=p.frames[ligaGame][f];for(const [k,id] of [['a','liga-roll-a'],['b','liga-roll-b'],['c','liga-roll-c'],['monitor','liga-checkpoint']]){document.getElementById(id).value=r[k]===null?'':r[k]}document.getElementById('liga-kind').value=r.kind||'';document.getElementById('liga-roll-third-label').style.display=f===9?'':'none'}
function ligaSaveRolls(){const f=Number(document.getElementById('liga-frame').value)-1,p=ligaCurrent().players[ligaSelected],r=p.frames[ligaGame][f];const a=document.getElementById('liga-roll-a').value,b=document.getElementById('liga-roll-b').value,c=document.getElementById('liga-roll-c').value;const n=x=>x===''?null:ligaNumber(x);if([a,b,c].some(v=>v!==''&&n(v)===null))return alert('Cada lanzamiento debe estar entre 0 y 10.');if(f<9&&n(a)!==null&&n(a)!==10&&n(b)!==null&&n(a)+n(b)>10)return alert('En un cuadro abierto no pueden derribarse más de 10 bolos.');r.a=n(a);r.b=f<9&&n(a)===10?null:n(b);r.c=f===9?n(c):null;if(f===9&&r.a!==null&&r.b!==null){if(r.a!==10&&r.a+r.b>10)return alert('El décimo cuadro supera los 10 bolos en dos tiros.');if(r.a===10&&r.b!==10&&r.c!==null&&r.b+r.c>10)return alert('Revisa los tiros extra del décimo cuadro.');if(r.a<10&&r.a+r.b<10&&r.c!==null)return alert('Sin pleno o semi no hay tercer tiro en el décimo cuadro.');}if(f<9)r.kind=r.a===10?'X':r.a!==null&&r.b!==null&&r.a+r.b===10?'/':r.a!==null&&r.b!==null?'O':r.kind;ligaSave();render()}
